package com.hs.jxc.pur;

import com.hs.jxc.attachment.*;
import com.hs.jxc.common.api.*;
import com.hs.jxc.common.audit.AuditWriter;
import com.hs.jxc.common.context.RequestContext;
import com.hs.jxc.common.idempotency.IdempotencyExecutor;
import com.hs.jxc.sys.api.Access;
import com.hs.jxc.sys.service.*;
import java.math.*;
import java.time.LocalDate;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/** 采购导入的唯一暂存写入口；不调用正式商品或采购创建。 */
@Service
public class PurchaseImportService {
    @org.springframework.beans.factory.annotation.Value("${jxc.purchase-import.worker-enabled:false}") private boolean workerEnabled;
    static final String BASE="/api/v1/pur/order-imports";
    static final List<String> FIELDS=List.of("sourceOrderNo","photo","productSpec","purchaseQty","saleUnitPrice","saleTotal","purchaseUnitPrice","freight","landedUnitCost","usdUnitCost","usdTotal");
    static final List<String> COLUMNS=List.of("source_order_no","photo","product_spec","purchase_qty","sale_unit_price","sale_total","purchase_unit_price","freight","landed_unit_cost","usd_unit_cost","usd_total");
    final JdbcTemplate jdbc;final JsonCodec json;final AuthorizationService auth;final TransactionTemplate tx;
    private final AttachmentAssetService assets;private final IdempotencyExecutor commands;private final AuditWriter audit;
    public PurchaseImportService(JdbcTemplate jdbc,JsonCodec json,AuthorizationService auth,AttachmentAssetService assets,IdempotencyExecutor commands,AuditWriter audit,PlatformTransactionManager tm){this.jdbc=jdbc;this.json=json;this.auth=auth;this.assets=assets;this.commands=commands;this.audit=audit;tx=new TransactionTemplate(tm);}
    Access access(RequestContext ctx,boolean write){
        Access a=auth.authorize(ctx);a.requireCountry();a.require("pur:order:create");
        for(String group:List.of("COST","CUSTOMER_PRICE","ORDER_TOTAL"))if(FieldPolicyService.rank(a.fieldGroups().get(group))<(write?2:1))throw ApiException.forbidden();
        return a;
    }
    @org.springframework.beans.factory.annotation.Value("${jxc.purchase-import.draft-creation.enabled:false}") private boolean draftCreationEnabled;
    public Map<String,Object> capabilities(RequestContext ctx){return tx.execute(s->{Access a=auth.authorize(ctx);a.requireCountry();var out=new LinkedHashMap<String,Object>();out.put("canCreatePurchase",a.has("pur:order:create"));out.put("draftCreationEnabled",draftCreationEnabled);out.put("canQueryProducts",a.has("md:product:view"));out.put("canMaintainGlobalProducts",a.platformAdmin()&&a.has("md:product:edit"));out.put("canConfigureCountrySku",a.has("md:country-sku:edit"));out.put("sourceLimitBytes",AttachmentAssetService.Policy.PURCHASE_SOURCE.maxBytes);out.put("imageLimitBytes",AttachmentAssetService.Policy.PURCHASE_IMAGE.maxBytes);out.put("expandedLimitBytes",512*1024*1024);out.put("fieldPolicies",a.fieldGroups());return out;});}
    Map<String,Object> batch(Access a,UUID batch,boolean lock){
        var rows=jdbc.queryForList("SELECT * FROM pur_order_import_batch WHERE country_id=? AND batch_id=?"+(lock?" FOR UPDATE":""),a.requireCountry(),batch);
        if(rows.size()!=1)throw ApiException.notFound();var b=rows.getFirst();
        if(number(b,"created_by")!=a.userId()||!a.canBook(Inputs.id(map(b.get("header")).get("bookId"))))throw ApiException.notFound();
        return b;
    }
    Map<String,Object> header(Access a,Map<String,Object> input){
        Map<String,Object> h=new LinkedHashMap<>();long book=Inputs.id(input.get("bookId")),supplier=Inputs.id(input.get("supplierId"));
        if(!a.canBook(book)||jdbc.queryForObject("SELECT count(*) FROM fin_book WHERE country_id=? AND id=? AND status='ACTIVE'",Integer.class,a.requireCountry(),book)!=1)throw ApiException.notFound();
        if(jdbc.queryForObject("SELECT count(*) FROM md_supplier WHERE country_id=? AND id=? AND status='ENABLED'",Integer.class,a.requireCountry(),supplier)!=1)throw Inputs.bad("供应商不存在或未启用");
        String currency=Inputs.required(input,"currency");if(!currency.matches("[A-Z]{3}")||jdbc.queryForObject("SELECT count(*) FROM md_currency WHERE code=? AND status='ENABLED'",Integer.class,currency)!=1)throw Inputs.bad("币种不存在或未启用");
        h.put("bookId",book);h.put("supplierId",supplier);h.put("currency",currency);h.put("orderDate",date(input.get("orderDate"),false));h.put("expectedDate",date(input.get("expectedDate"),true));
        String terms=Inputs.text(input,"paymentTerms","");if(terms.length()>200)throw Inputs.bad("付款条件最多200字");h.put("paymentTerms",terms);
        BigDecimal ratio=decimal(input.get("prepayRatio"),6,1,false);if(ratio!=null&&ratio.compareTo(BigDecimal.ONE)>0)throw Inputs.bad("预付比例须为0至1");h.put("prepayRatio",ratio==null?null:ratio.stripTrailingZeros().toPlainString());
        Object days=input.get("termDays");if(days!=null&&(!(days instanceof Number)||new BigDecimal(days.toString()).scale()>0||((Number)days).longValue()<0||((Number)days).longValue()>Integer.MAX_VALUE))throw Inputs.bad("账期天数须为非负整数");h.put("termDays",days==null?null:((Number)days).intValue());return h;
    }
    static String date(Object value,boolean optional){if(optional&&(value==null||"".equals(value)))return null;if(!(value instanceof String text)||!text.matches("\\d{4}-\\d{2}-\\d{2}"))throw Inputs.bad("日期格式不正确");try{return LocalDate.parse(text).toString();}catch(java.time.DateTimeException e){throw Inputs.bad("日期无效");}}
    static BigDecimal decimal(Object value,int scale,int digits,boolean positive){
        if(value==null||"".equals(value)){if(positive)throw Inputs.bad("采购数量须大于0");return null;}
        if(!(value instanceof String text)||!text.matches("\\d{1,"+digits+"}(\\.\\d{1,"+scale+"})?"))throw Inputs.bad("数值须为符合字段精度的十进制字符串");
        BigDecimal n=new BigDecimal(text);if(positive&&n.signum()<=0)throw Inputs.bad("采购数量须大于0");return n.setScale(scale);
    }
    static Map<String,Object> values(Map<String,Object> input){
        var out=new LinkedHashMap<String,Object>();if(!input.keySet().equals(new HashSet<>(FIELDS)))throw Inputs.bad("导入明细字段不完整或包含不可编辑字段");
        for(int i=0;i<FIELDS.size();i++){String field=FIELDS.get(i);Object value=input.get(field);if(i<3){if(value!=null&&!(value instanceof String))throw Inputs.bad("文字字段格式不正确");String text=value==null?null:value.toString().trim();out.put(field,text==null||text.isEmpty()?null:text);}else out.put(field,decimal(value,i==3?4:10,i==3?16:20,i==3));}
        Object source=out.get("sourceOrderNo");if(source==null||source.toString().length()>100)throw Inputs.bad("采购单号不能为空或超过100字");return out;
    }
    public Map<String,Object> upload(RequestContext ctx,String name,byte[] bytes,Map<String,Object> input,UUID existing,String key){
        if(!workerEnabled)throw new ApiException(503,"PARSER_DISABLED","采购解析后台尚未启用，文件未导入；请联系管理员完成受限桥接配置");
        if(name==null||!name.toLowerCase(Locale.ROOT).endsWith(".xlsx"))throw Inputs.bad("请上传.xlsx采购模板");
        var h=tx.execute(s->{Access a=access(ctx,true);if(existing!=null){var b=batch(a,existing,false);if(!sameHeader(map(b.get("header")),header(a,input)))throw Inputs.conflict();}return header(a,input);});
        var prepared=assets.prepare(ctx,AttachmentAssetService.Policy.PURCHASE_SOURCE,name,"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",bytes);
        return tx.execute(s->{Access a=access(ctx,true);var checked=header(a,h);var intent=new LinkedHashMap<String,Object>();intent.put("header",checked);intent.put("fileSha256",prepared.sha256());intent.put("fileName",name);intent.put("batchId",existing==null?null:existing.toString());
            return commands.execute(ctx,"POST",BASE,key,intent,Inputs.id(h.get("bookId")),()->{
                UUID id=existing==null?UUID.randomUUID():existing;
                if(existing==null)jdbc.update("INSERT INTO pur_order_import_batch(country_id,batch_id,header,status,created_by) VALUES(?,?,?::jsonb,'PARSING',?)",a.requireCountry(),id,json.write(checked),a.userId());
                var b=batch(a,id,true);if(existing!=null&&!sameHeader(map(b.get("header")),checked))throw Inputs.conflict();
                long asset=assets.register(ctx,prepared);long source=jdbc.queryForObject("INSERT INTO pur_order_import_source(country_id,batch_id,attachment_id,file_name,file_sha256) VALUES(?,?,?,?,?) RETURNING id",Long.class,a.requireCountry(),id,asset,name,prepared.sha256());
                UUID task=UUID.randomUUID();jdbc.update("INSERT INTO pur_order_import_task(id,country_id,batch_id,source_id,input_revision,input_hash,requested_by,authorization_basis) VALUES(?,?,?,?,?,?,?,?::jsonb)",task,a.requireCountry(),id,source,number(b,"version"),prepared.sha256(),a.userId(),json.write(Map.of("userId",a.userId(),"tokenHash",ctx.tokenHash())));
                jdbc.update("UPDATE pur_order_import_batch SET status='PARSING',updated_at=clock_timestamp() WHERE country_id=? AND batch_id=?",a.requireCountry(),id);
                audit.append(ctx,"PUR_IMPORT_UPLOAD","PURCHASE_IMPORT",number(b,"id"),null,Map.of("sourceId",source,"sha256",prepared.sha256()));var result=snapshot(a,id);result.put("taskId",task.toString());return result;
            },r->batch(a,UUID.fromString(r.get("batchId").toString()),false));
        });
    }
    public Map<String,Object> get(RequestContext ctx,UUID id){return tx.execute(s->snapshot(access(ctx,false),id));}
    Map<String,Object> snapshot(Access a,UUID id){
        var b=batch(a,id,false);var out=new LinkedHashMap<String,Object>();out.put("batchId",id.toString());out.put("version",b.get("version"));out.put("status",b.get("status"));out.put("sourceStatus",b.get("source_status"));out.put("header",map(b.get("header")));
        out.put("rows",jdbc.queryForList("SELECT * FROM pur_order_import WHERE country_id=? AND batch_id=? ORDER BY row_no",a.requireCountry(),id).stream().map(this::rowDto).toList());out.put("groups",jdbc.queryForList("SELECT * FROM pur_order_import_group WHERE country_id=? AND batch_id=? ORDER BY id",a.requireCountry(),id).stream().map(this::groupDto).toList());
        out.put("sources",jdbc.queryForList("SELECT id,file_name,file_sha256,parser_version,status,sheets,warnings,associations,error_code,error_message FROM pur_order_import_source WHERE country_id=? AND batch_id=? ORDER BY id",a.requireCountry(),id).stream().map(this::sourceDto).toList());
        out.put("tasks",jdbc.queryForList("SELECT id,kind,status,attempt_count,error_code,error_message,result FROM pur_order_import_task WHERE country_id=? AND batch_id=? ORDER BY created_at",a.requireCountry(),id).stream().map(this::taskDto).toList());return out;
    }
    Map<String,Object> groupDto(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();out.put("id",row.get("id"));out.put("version",row.get("version"));out.put("sourceOrderNo",row.get("source_order_no"));out.put("header",map(row.get("effective_header")));out.put("createStatus",row.get("create_status"));out.put("verifyStatus",row.get("verify_status"));out.put("previewToken",row.get("preview_token")==null?null:row.get("preview_token").toString());out.put("orderId",row.get("target_order_id"));out.put("errorCode",row.get("error_code"));out.put("errorMessage",row.get("error_message"));out.put("preview",row.get("preview_snapshot")==null?null:map(row.get("preview_snapshot")).get("preview"));out.put("errors",row.get("preview_snapshot")==null?List.of():map(row.get("preview_snapshot")).get("errors"));if(row.get("outer_key")!=null&&row.get("create_request")!=null)out.put("createIntent",Map.of("key",row.get("outer_key").toString(),"request",map(row.get("create_request"))));if(row.get("result_snapshot")!=null){var result=map(row.get("result_snapshot"));out.put("docNo",result.get("docNo"));out.put("orderStatus",result.get("status"));}return out;}
    Map<String,Object> taskDto(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","kind","phase","status","attempt_count","error_code","error_message"))out.put(camel(k),row.get(k)==null?null:row.get(k) instanceof UUID?row.get(k).toString():row.get(k));if(row.get("result")!=null)out.put("result",map(row.get("result")));return out;}
    private Map<String,Object> sourceDto(Map<String,Object> r){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","file_name","file_sha256","parser_version","status","error_code","error_message"))out.put(camel(k),r.get(k));for(String k:List.of("sheets","warnings","associations"))out.put(k,json.read(r.get(k).toString(),List.class));return out;}
    Map<String,Object> rowDto(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();out.put("id",row.get("id"));out.put("version",row.get("version"));out.put("rowNo",row.get("row_no"));for(int i=0;i<FIELDS.size();i++){Object v=row.get(COLUMNS.get(i));out.put(FIELDS.get(i),v instanceof BigDecimal d?d.toPlainString():v);}for(String k:List.of("source_id","source_sheet","source_row","group_id","target_order_line_id"))out.put(camel(k),row.get(k));for(String field:List.of("matched_product_id","purchase_unit","supplied_product_code","supplied_product_name","supplier_product_code","decision","readiness","confirmed_by","confirmed_at")){Object value=row.get(field);out.put(camel(field),value instanceof java.sql.Timestamp timestamp?timestamp.toInstant().toString():value);}for(String field:List.of("product_snapshot","product_operation"))out.put(camel(field),row.get(field)==null?null:map(row.get(field)));out.put("setupReasons",json.read(row.get("setup_reasons").toString(),List.class));out.put("images",jdbc.queryForList("SELECT i.id,i.image_sha256,r.association_status,r.anchor,r.publish_status,r.product_image_id,r.publish_product_id,r.publish_error FROM pur_order_import_row_image r JOIN pur_order_import_image i ON i.country_id=r.country_id AND i.id=r.image_id WHERE r.country_id=? AND r.row_id=? ORDER BY i.id",row.get("country_id"),row.get("id")).stream().map(this::imageDto).toList());return out;}
    private Map<String,Object> imageDto(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();out.put("id",row.get("id"));out.put("sha256",row.get("image_sha256"));out.put("status",row.get("association_status"));out.put("anchor",map(row.get("anchor")));out.put("publishStatus",row.get("publish_status"));out.put("productImageId",row.get("product_image_id"));out.put("publishedProductId",row.get("publish_product_id"));out.put("publishError",row.get("publish_error"));return out;}
    Map<String,Object> row(Access a,UUID batch,long id){var rows=jdbc.queryForList("SELECT * FROM pur_order_import WHERE country_id=? AND batch_id=? AND id=? FOR UPDATE",a.requireCountry(),batch,id);if(rows.size()!=1)throw ApiException.notFound();return rows.getFirst();}
    public Map<String,Object> saveRow(RequestContext ctx,UUID id,long rowId,Map<String,Object> input){return tx.execute(s->{Access a=access(ctx,true);var b=batch(a,id,true);var before=row(a,id,rowId);requireEditable(before);if(number(before,"version")!=Inputs.version(input))throw Inputs.conflict();var v=values(map(input.get("values")));var args=new ArrayList<Object>();String assignments=String.join(",",java.util.stream.IntStream.range(0,FIELDS.size()).mapToObj(i->{args.add(v.get(FIELDS.get(i)));return COLUMNS.get(i)+"=?";}).toList());var origins=map(before.get("field_origins"));v.forEach((k,value)->{if(!Objects.equals(Objects.toString(before.get(COLUMNS.get(FIELDS.indexOf(k))),null),Objects.toString(value,null)))origins.put(k,"MANUAL");});args.add(json.write(origins));args.add(a.requireCountry());args.add(rowId);
        jdbc.update("UPDATE pur_order_import SET "+assignments+",field_origins=?::jsonb,decision='UNRESOLVED',readiness='UNRESOLVED',confirmed_by=NULL,confirmed_at=NULL,product_snapshot=NULL,version=version+1,updated_at=clock_timestamp() WHERE country_id=? AND id=?",args.toArray());touch(a,id);var out=rowDto(row(a,id,rowId));out.put("batchVersion",number(b,"version")+1);audit.append(ctx,"PUR_IMPORT_EDIT","PURCHASE_IMPORT",number(b,"id"),Map.of("rowId",rowId,"version",before.get("version")),Map.of("rowId",rowId,"version",out.get("version")));return out;});}
    public Map<String,Object> saveHeader(RequestContext ctx,UUID id,Map<String,Object> input){return tx.execute(s->{Access a=access(ctx,true);var b=batch(a,id,true);requireResolvedBatch(a,id);if(jdbc.queryForObject("SELECT count(*) FROM pur_order_import WHERE country_id=? AND batch_id=? AND target_order_line_id IS NOT NULL",Integer.class,a.requireCountry(),id)>0)throw new ApiException(409,"PUR_IMPORT_CREATED_READ_ONLY","已创建草稿的来源基础信息不能整体修改");if(number(b,"version")!=Inputs.id(input.get("batchVersion")))throw Inputs.conflict();var current=jdbc.queryForList("SELECT id,version FROM pur_order_import WHERE country_id=? AND batch_id=? ORDER BY id FOR UPDATE",a.requireCountry(),id);var versions=list(input.get("versions"));if(current.size()!=versions.size()||current.stream().anyMatch(r->versions.stream().noneMatch(v->Inputs.id(v.get("id"))==number(r,"id")&&Inputs.id(v.get("version"))==number(r,"version"))))throw Inputs.conflict();var h=header(a,map(input.get("header")));jdbc.update("UPDATE pur_order_import_batch SET header=?::jsonb WHERE country_id=? AND batch_id=?",json.write(h),a.requireCountry(),id);jdbc.update("UPDATE pur_order_import SET book_id=?,supplier_id=?,currency=?,order_date=?::date,expected_date=?::date,payment_terms=?,prepay_ratio=?::numeric,term_days=?,version=version+1,updated_at=clock_timestamp() WHERE country_id=? AND batch_id=?",h.get("bookId"),h.get("supplierId"),h.get("currency"),h.get("orderDate"),h.get("expectedDate"),h.get("paymentTerms"),h.get("prepayRatio"),h.get("termDays"),a.requireCountry(),id);jdbc.update("UPDATE pur_order_import_group SET effective_header=?::jsonb WHERE country_id=? AND batch_id=? AND header_override=false AND target_order_id IS NULL",json.write(h),a.requireCountry(),id);touch(a,id);audit.append(ctx,"PUR_IMPORT_HEADER","PURCHASE_IMPORT",number(b,"id"),map(b.get("header")),h);return snapshot(a,id);});}
    public Map<String,Object> deleteRow(RequestContext ctx,UUID id,long rowId,long version){return tx.execute(s->{Access a=access(ctx,true);var b=batch(a,id,true);var r=row(a,id,rowId);requireEditable(r);if(number(r,"version")!=version)throw Inputs.conflict();jdbc.update("DELETE FROM pur_order_import WHERE country_id=? AND id=?",a.requireCountry(),rowId);touch(a,id);audit.append(ctx,"PUR_IMPORT_DELETE","PURCHASE_IMPORT",number(b,"id"),Map.of("rowId",rowId),null);return Map.of("deleted",true,"id",rowId,"batchVersion",number(b,"version")+1);});}
    void requireResolvedBatch(Access a,UUID id){if(jdbc.queryForObject("SELECT count(*) FROM pur_order_import_group WHERE country_id=? AND batch_id=? AND create_status IN ('UNKNOWN','CREATING')",Integer.class,a.requireCountry(),id)>0)throw new ApiException(409,"PUR_IMPORT_CREATE_UNRESOLVED","请先按原请求核实采购创建结果");}
    void requireEditable(Map<String,Object> row){if(row.get("group_id")!=null&&jdbc.queryForObject("SELECT count(*) FROM pur_order_import_group WHERE country_id=? AND id=? AND create_status IN ('UNKNOWN','CREATING')",Integer.class,row.get("country_id"),row.get("group_id"))>0)throw new ApiException(409,"PUR_IMPORT_CREATE_UNRESOLVED","请先按原请求核实采购创建结果");if(row.get("target_order_line_id")!=null)throw new ApiException(409,"PUR_IMPORT_CREATED_READ_ONLY","本行已关联真实采购草稿，不能修改或删除来源");}
    void touch(Access a,UUID id){jdbc.update("UPDATE pur_order_import_group SET preview_token=NULL,preview_snapshot=NULL,create_status='DRAFT',version=version+1 WHERE country_id=? AND batch_id=? AND target_order_id IS NULL AND create_status NOT IN ('CREATING','UNKNOWN')",a.requireCountry(),id);jdbc.update("UPDATE pur_order_import_batch SET version=version+1,updated_at=clock_timestamp() WHERE country_id=? AND batch_id=?",a.requireCountry(),id);}
    public AttachmentService.Download content(RequestContext ctx,UUID id,long assetId,boolean image){var snap=tx.execute(s->{Access a=access(ctx,false);batch(a,id,false);var r=jdbc.queryForList(image?"SELECT a.* FROM pur_order_import_image i JOIN pur_order_import_source s ON s.country_id=i.country_id AND s.id=i.source_id JOIN sys_attachment a ON a.country_id=i.country_id AND a.id=i.attachment_id WHERE i.country_id=? AND s.batch_id=? AND i.id=? AND a.status='VALID' AND a.object_status='AVAILABLE'":"SELECT a.* FROM pur_order_import_source s JOIN sys_attachment a ON a.country_id=s.country_id AND a.id=s.attachment_id WHERE s.country_id=? AND s.batch_id=? AND s.id=? AND a.status='VALID' AND a.object_status='AVAILABLE'",a.requireCountry(),id,assetId);if(r.size()!=1)throw ApiException.notFound();return r.getFirst();});byte[] data=assets.read(snap,image?AttachmentAssetService.Policy.PURCHASE_IMAGE:AttachmentAssetService.Policy.PURCHASE_SOURCE);tx.execute(s->{Access a=access(ctx,false);batch(a,id,false);return null;});return new AttachmentService.Download(snap.get("file_name").toString(),snap.get("content_type").toString(),data);}
    public Map<String,Object> associate(RequestContext ctx,UUID id,long rowId,long imageId,Map<String,Object> input){return tx.execute(s->{Access a=access(ctx,true);batch(a,id,true);var r=row(a,id,rowId);requireEditable(r);if(number(r,"version")!=Inputs.version(input))throw Inputs.conflict();String state=Inputs.required(input,"association");if(!Set.of("CONFIRMED","REJECTED").contains(state))throw Inputs.bad("请明确确认或排除图片归属");if(jdbc.queryForObject("SELECT count(*) FROM pur_order_import_row_image WHERE country_id=? AND row_id=? AND image_id=? AND product_image_id IS NOT NULL",Integer.class,a.requireCountry(),rowId,imageId)>0)throw new ApiException(409,"PUR_IMPORT_PHOTO_PUBLISHED","照片已形成正式商品关系，导入区不能直接撤销归属");if(jdbc.update("UPDATE pur_order_import_row_image SET association_status=?,confirmed_by=?,confirmed_at=clock_timestamp() WHERE country_id=? AND row_id=? AND image_id=?",state,a.userId(),a.requireCountry(),rowId,imageId)!=1)throw ApiException.notFound();jdbc.update("UPDATE pur_order_import SET version=version+1 WHERE country_id=? AND id=?",a.requireCountry(),rowId);touch(a,id);audit.append(ctx,"PUR_IMPORT_IMAGE_ASSOCIATION","PURCHASE_IMPORT",rowId,null,Map.of("imageId",imageId,"association",state));var out=rowDto(row(a,id,rowId));out.put("batchVersion",jdbc.queryForObject("SELECT version FROM pur_order_import_batch WHERE country_id=? AND batch_id=?",Integer.class,a.requireCountry(),id));return out;});}
    Map<String,Object> map(Object value){if(value instanceof Map<?,?> m){var out=new LinkedHashMap<String,Object>();m.forEach((k,v)->out.put(k.toString(),v));return out;}if(value instanceof org.postgresql.util.PGobject) return json.readMap(value.toString());throw Inputs.bad("对象字段格式不正确");}
    static List<Map<String,Object>> list(Object value){if(!(value instanceof List<?> list))throw Inputs.bad("列表字段格式不正确");var out=new ArrayList<Map<String,Object>>();for(Object item:list){if(!(item instanceof Map<?,?> m))throw Inputs.bad("列表项格式不正确");var row=new LinkedHashMap<String,Object>();m.forEach((k,v)->row.put(k.toString(),v));out.add(row);}return out;}
    static long number(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
    private boolean sameHeader(Map<String,Object> left,Map<String,Object> right){return json.write(IdempotencyExecutor.canonical(normalizedHeader(left))).equals(json.write(IdempotencyExecutor.canonical(normalizedHeader(right))));}
    private Map<String,Object> normalizedHeader(Map<String,Object> value){var copy=new LinkedHashMap<>(value);if(copy.get("prepayRatio")!=null)copy.put("prepayRatio",new BigDecimal(copy.get("prepayRatio").toString()).stripTrailingZeros().toPlainString());return copy;}
    private static String camel(String key){StringBuilder s=new StringBuilder();boolean up=false;for(char c:key.toCharArray())if(c=='_')up=true;else{s.append(up?Character.toUpperCase(c):c);up=false;}return s.toString();}
}
